import{_ as e,o,c as r,a2 as d}from"./chunks/framework.CuUVYbLV.js";const u=JSON.parse('{"title":"教程总览与学习路径","description":"rolebox 教程入口：四条学习路径、七章教程地图，以及动手前的准备。","frontmatter":{"title":"教程总览与学习路径","description":"rolebox 教程入口：四条学习路径、七章教程地图，以及动手前的准备。"},"headers":[],"relativePath":"02-Guide/getting-started.md","filePath":"02-Guide/getting-started.md"}'),a={name:"02-Guide/getting-started.md"};function l(i,t,h,s,n,c){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="教程总览与学习路径-getting-started" tabindex="-1">教程总览与学习路径（Getting Started） <a class="header-anchor" href="#教程总览与学习路径-getting-started" aria-label="Permalink to &quot;教程总览与学习路径（Getting Started）&quot;">​</a></h1><p>rolebox 把一个通用的 AI 编码助手变成你用 YAML 定义的团队：每个角色带自己的提示词、技能与函数，多代理流程由**图执行引擎（graph execution engine，运行时按节点与边推进工作流的调度器）**编排。这一页帮你决定从哪条路径进入，并给出七章教程的地图。</p><h2 id="四条学习路径" tabindex="-1">四条学习路径 <a class="header-anchor" href="#四条学习路径" aria-label="Permalink to &quot;四条学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的目标</th><th>从这里开始</th><th>读完你会</th></tr></thead><tbody><tr><td>只想用现成角色</td><td><a href="/rolebox-docs/01-Overview/quick-start.html">三步速查</a> → <a href="/rolebox-docs/03-Reference/registry.html">注册中心</a></td><td>装好插件，把一个角色跑起来</td></tr><tr><td>想写自己的角色</td><td><a href="/rolebox-docs/02-Guide/tutorial/01-install.html">教程 01 安装并跑通第一个角色</a> → <a href="/rolebox-docs/02-Guide/create-a-role.html">创建角色</a></td><td>会写 PROMPT、技能、引用文档与函数</td></tr><tr><td>想编排多代理</td><td><a href="/rolebox-docs/02-Guide/tutorial/04-team.html">教程 04 把角色变成团队</a> → <a href="/rolebox-docs/02-Guide/graph-workflows.html">图工作流</a></td><td>用图工具搭出一条带审批门的流水线</td></tr><tr><td>想贡献源码</td><td><a href="/rolebox-docs/05-Contributing/development-setup.html">开发环境搭建</a> → <a href="/rolebox-docs/05-Contributing/contributing.html">贡献指南</a></td><td>本地构建、跑测试、提交改动</td></tr></tbody></table><h2 id="教程地图" tabindex="-1">教程地图 <a class="header-anchor" href="#教程地图" aria-label="Permalink to &quot;教程地图&quot;">​</a></h2><p>七章走完，你会得到一个能真正干活的代码评审团队：父角色 <code>code-reviewer</code>，加上 <code>coder</code>、<code>reviewer</code>、<code>doc-writer</code> 三个子代理，最后由图引擎串成「实现 → 评审 → 定稿」的流水线。每一章都以「读者输入什么 / 应该看到什么」组织，命令都可以直接复制。</p><table tabindex="0"><thead><tr><th>章</th><th>你会做什么</th><th>完成后你拥有</th></tr></thead><tbody><tr><td><a href="/rolebox-docs/02-Guide/tutorial/01-install.html">01 安装并跑通第一个角色</a></td><td>安装 rolebox，创建 <code>code-reviewer</code>，在 harness 里对话</td><td>一个能跑起来的角色</td></tr><tr><td><a href="/rolebox-docs/02-Guide/tutorial/02-first-role.html">02 让角色懂你的项目</a></td><td>写 <code>PROMPT.md</code>，加一个技能与一份引用文档</td><td>懂你项目约定的角色</td></tr><tr><td><a href="/rolebox-docs/02-Guide/tutorial/03-functions.html">03 用函数改变行为</a></td><td>激活内置函数，再写一个自定义函数</td><td>能切换工作模式的角色</td></tr><tr><td><a href="/rolebox-docs/02-Guide/tutorial/04-team.html">04 把角色变成团队</a></td><td>在 <code>role.yaml</code> 里声明三个子代理</td><td>一个父子代理团队</td></tr><tr><td><a href="/rolebox-docs/02-Guide/tutorial/05-graph.html">05 用图引擎编排团队</a></td><td>用 <code>graph_*</code> 工具建图并运行</td><td>一条自动流水线</td></tr><tr><td><a href="/rolebox-docs/02-Guide/tutorial/06-approval-and-loop.html">06 加上审批门与有界循环</a></td><td>加 <code>needs_approval</code> 与 <code>max_traversals</code></td><td>有人工闸门、不会失控的流水线</td></tr><tr><td><a href="/rolebox-docs/02-Guide/tutorial/07-memory.html">07 让代理记住你</a></td><td>用 <code>rolebox memory</code> 观察记忆库</td><td>跨会话记得你决策的代理</td></tr></tbody></table><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li><strong>一个 harness</strong>：opencode、pi 或 dsh。教程主线走 opencode，另外两个的差异只在安装命令与目录，见<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>。</li><li><strong>Node.js 与 npm</strong>：rolebox 以 npm 包发布，opencode 与 dsh 的安装都走 npm。</li><li><strong>一个可以随意改动的练习目录</strong>：教程在 <code>~/rolebox-lab</code> 下建角色，不必碰你现有的项目。</li><li><strong>不需要</strong>预先了解图引擎或函数系统：术语在首次出现处就地解释，全站定义表见<a href="/rolebox-docs/06-Appendix/glossary.html">术语表</a>。</li></ul><h2 id="贡献-rolebox-源码" tabindex="-1">贡献 rolebox 源码 <a class="header-anchor" href="#贡献-rolebox-源码" aria-label="Permalink to &quot;贡献 rolebox 源码&quot;">​</a></h2><p>本页原先附带的贡献者指南（前提条件、克隆、构建、测试、调试）已整体移交<a href="/rolebox-docs/05-Contributing/development-setup.html">开发环境搭建</a>；贡献流程、提交信息规范与发布流程见<a href="/rolebox-docs/05-Contributing/contributing.html">贡献指南</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>从<a href="/rolebox-docs/02-Guide/tutorial/01-install.html">教程 01 安装并跑通第一个角色</a>开始。只有五分钟？先走<a href="/rolebox-docs/01-Overview/quick-start.html">三步速查</a>。</p>',13)])])}const m=e(a,[["render",l]]);export{u as __pageData,m as default};
